private func findNumber(_ num: Int) -> Bool {
  var tries = 0
  var nextDrawer = num - 1

  while tries < 50 {
    tries += 1

    switch strategy {
    case .random where drawers.randomElement()! == num:
      return true
    case .optimum where drawers[nextDrawer] == num:
      return true
    case .optimum:
      nextDrawer = drawers[nextDrawer] - 1
    case _:
      continue
    }
  }

  return false
}

func rounded(_ scale: Int, _ roundingMode: NSDecimalNumber.RoundingMode) -> Decimal {
  var result = Decimal()
  var localCopy = self
  NSDecimalRound(&result, &localCopy, scale, roundingMode)
  return result
}

func sense(adj: [Int]) {
    var bat = false
    var pit = false
    for ar in adj {
        if ar == wumpus {
            print("You smell something terrible nearby.")
        }
        switch ar {
        case bat1, bat2:
            if !bat {
                print("You hear rustling.")
                bat = true
            }
        case pit1, pit2:
            if !pit {
                print("You feel a cold wind blowing from a nearby cavern.")
                pit = true
            }
        default:
            print("")
        }
    }
}
